'use strict';
window.CampaignReadiness={open(campaignId){
 const dialog=document.createElement('dialog');dialog.className='client-dialog';dialog.style.width='min(980px,94vw)';dialog.style.maxWidth='980px';
 const heading=document.createElement('div');heading.className='dialog-heading';const title=document.createElement('h2');title.textContent='Проверка готовности';const close=document.createElement('button');close.className='outline';close.textContent='Закрыть';close.onclick=()=>dialog.close();heading.append(title,close);
 const description=document.createElement('p');description.textContent='Проверка сохранённой рассылки без отправки. Неподключённые проверки показаны отдельно; наличие отчёта не запускает и не разрешает реальную отправку.';
 const refresh=document.createElement('button');refresh.className='outline';refresh.textContent='Обновить проверку';const content=document.createElement('section'),status=document.createElement('p');status.setAttribute('role','status');dialog.append(heading,description,refresh,status,content);document.body.append(dialog);dialog.showModal();let token=0;
 dialog.onclose=()=>{token++;dialog.remove();};
 function text(tag,value){const e=document.createElement(tag);e.textContent=value;return e;}
 function table(host,headers,rows){const wrap=document.createElement('div');wrap.className='table-scroll';const table=document.createElement('table'),head=document.createElement('tr');for(const value of headers)head.append(text('th',value));table.append(head);for(const values of rows){const row=document.createElement('tr');for(const value of values)row.append(text('td',String(value)));table.append(row);}wrap.append(table);host.append(wrap);}
 async function load(){const request=++token;refresh.disabled=true;status.textContent='Пересчёт и проверка…';try{const data=await api(`/api/campaigns/${campaignId}/readiness`);if(request!==token||!dialog.open)return;content.replaceChildren();title.textContent='Готовность: '+data.campaign_name;
  const verdict=text('p',data.verdict==='needs_changes'?'Есть препятствия для запуска. Исправьте замечания и повторите проверку.':'Подготовка проверена. До реальной отправки остаются подключения и подтверждения.');verdict.style.fontWeight='600';verdict.style.color=data.verdict==='needs_changes'?'#b42318':'#916100';content.append(verdict,text('p',`Ошибок: ${data.summary.fail} · Замечаний: ${data.summary.warning} · Ожидают подключения/подтверждения: ${data.summary.pending} · Готово: ${data.summary.pass}`),text('p',`Проверено: ${new Date(data.checked_at).toLocaleString('ru-RU')} · Версия черновика: ${data.campaign_revision} · Основа: ${data.queue_id?'зафиксированная очередь':'текущие аудитории'}`));
  const counters=document.createElement('div');counters.className='cmp-count-grid';for(const [label,value]of [['Уникальных email',data.recipients.total],['Ожидают обработки',data.recipients.awaiting],['Технически допущено',data.recipients.technical_ready],['Не допущено сейчас',data.recipients.excluded_now],['Обработано / отменено',data.recipients.processed]]){const box=text('div',label);box.append(text('strong',String(value)));counters.append(box);}content.append(counters);
  content.append(text('h3','Сведения о согласии для всего состава'));table(content,['Подтверждено источником','Неизвестно','Отозвано'],[[data.consent.confirmed,data.consent.unknown,data.consent.revoked]]);
  const labels={pass:'Готово',warning:'Внимание',fail:'Исправить',pending:'Ожидает подтверждения/подключения'},colors={pass:'#16835e',warning:'#c18418',fail:'#b42318',pending:'#7890a2'};
  for(const section of [...new Set(data.checks.map(c=>c.section))]){content.append(text('h3',section));for(const check of data.checks.filter(c=>c.section===section)){const box=document.createElement('div');box.style.cssText=`border:1px solid #dde5ec;border-left:4px solid ${colors[check.status]};border-radius:6px;padding:12px;margin:10px 0`;box.append(text('strong',`${labels[check.status]} · ${check.title}`),text('p',check.detail));content.append(box);}}
  if(data.template_findings.length){const details=document.createElement('details');details.append(text('summary','Ошибки и замечания шаблона'));for(const finding of data.template_findings)details.append(text('p',`${finding.level==='error'?'Ошибка':'Замечание'}: ${finding.message}`));content.append(details);}
  if(data.personalization.samples.length){content.append(text('h3','Примеры проблем персонализации — до 10 адресов'));table(content,['Email','Нет данных','Неоднозначный клиент','Тема','Ссылки'],data.personalization.samples.map(row=>[row.email,row.missing.join(', ')||'—',row.ambiguous?'Да':'—',row.subject_error?'Ошибка':'—',row.link_error?'Ошибка':'—']));}
  content.append(text('p',data.note));status.textContent='';
 }catch(e){if(request===token)status.textContent=e.message;}finally{if(request===token)refresh.disabled=false;}}
 refresh.onclick=load;load();
}};
